import re
from typing import List, Dict, Any, Optional

# helpers assumed to exist in the evaluation environment
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> list of nodes belonging to the scope
# table_rows(node) -> list of (row_index, {column:cell})

#-----------------------------------------------------------------------
# Utility helpers ------------------------------------------------------
#-----------------------------------------------------------------------
def _object_id_from_line(line: str) -> Optional[str]:
    """
    Extract object id as a string from an 'Object X:' line.
    """
    m = re.match(r"Object\s+(\d+):", line)
    return m.group(1) if m else None

def _event_objects(line: str) -> List[str]:
    """
    Extract all object ids mentioned in a line.
    """
    return re.findall(r"Object\s+(\d+)", line)

def _parse_motion_row(row: Dict[str, str]) -> Dict[str, Any]:
    """
    Convert a motion table row dict to proper types.
    """
    def try_float(v: str) -> Any:
        try:
            return float(v)
        except:
            return v
    out = {}
    for k, v in row.items():
        if k == "frame" or k == "object":
            out[k] = v
            continue
        try:
            out[k] = float(v)
        except:
            out[k] = v
    return out

#-----------------------------------------------------------------------
# Main interface --------------------------------------------------------
#-----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    List every distinct entity the scope's records are about, with a
    human‑readable description.
    """
    entities = []
    obj_node = node_by_title(doc, f"{scope}: Objects")
    if not obj_node:
        return entities
    for line in obj_node.get("lines", []):
        obj_id = _object_id_from_line(line)
        if obj_id is None:
            continue
        # description is the part after the colon
        desc = line.split(":", 1)[1].strip()
        entities.append({"id": obj_id, "description": desc})
    return entities


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    The last time point covered by the scope's records.
    """
    max_frame = None

    # events
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node and ev_node.get("kind") == "list":
        for line in ev_node.get("lines", []):
            m = re.match(r"Frame\s+(\d+):", line)
            if m:
                f = int(m.group(1))
                if max_frame is None or f > max_frame:
                    max_frame = f

    # motion log
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    if ml_node and ml_node.get("kind") == "table":
        rows = ml_node.get("table", {}).get("rows", [])
        for r in rows:
            try:
                f = int(r[0])
                if max_frame is None or f > max_frame:
                    max_frame = f
            except:
                continue

    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Everything that enters the process from outside and is not caused by it.
    """
    inputs = []

    # --- gather objects and initial description ---
    obj_node = node_by_title(doc, f"{scope}: Objects")
    if not obj_node:
        return inputs
    obj_desc = {}
    for line in obj_node.get("lines", []):
        obj_id = _object_id_from_line(line)
        if obj_id:
            obj_desc[obj_id] = line.split(":", 1)[1].strip()

    # --- motion log data, indexed by object id ---
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    motion_by_obj = {}
    if ml_node and ml_node.get("kind") == "table":
        rows = ml_node.get("table", {}).get("rows", [])
        for r in rows:
            try:
                frame = int(r[0])
            except:
                continue
            obj_col = r[1]
            # obj_col is like '1 blue rubber cylinder'
            m = re.match(r"(\d+)\s", obj_col)
            if not m:
                continue
            obj_id = m.group(1)
            data = {
                "frame": frame,
                "x": float(r[2]),
                "y": float(r[3]),
                "vx": float(r[4]),
                "vy": float(r[5]),
                "speed": float(r[6]),
                "node_id": ml_node["node_id"],
                "row_index": rows.index(r),
                "row_data": r,
            }
            motion_by_obj.setdefault(obj_id, []).append(data)

    # --- events ---
    ev_node = node_by_title(doc, f"{scope}: Events")
    event_lines = ev_node.get("lines", []) if ev_node else []

    # Map object id -> (frame, action)
    obj_events = {}
    for i, line in enumerate(event_lines):
        m = re.match(r"Frame\s+(\d+):", line)
        if not m:
            continue
        frame = int(m.group(1))
        objects = _event_objects(line)
        if not objects:
            continue
        # Determine type
        if "enters" in line or "in view" in line:
            for oid in objects:
                # store earliest arrival
                if oid not in obj_events or frame < obj_events[oid][0]:
                    obj_events[oid] = (frame, "arrival")
        elif "exits" in line:
            # exit handled elsewhere
            continue

    # --- determine inputs for each object ---
    seen_inputs = set()
    for oid, (frame, evtype) in obj_events.items():
        if oid not in motion_by_obj:
            continue
        # find first motion record at or after frame
        recs = sorted(motion_by_obj[oid], key=lambda d: d["frame"])
        rec = None
        for r in recs:
            if r["frame"] >= frame:
                rec = r
                break
        if rec is None:
            rec = recs[0] if recs else None
        if not rec:
            continue

        # build input
        in_id = f"input_obj{oid}_{frame}"
        fields = {
            "frame": rec["frame"],
            "x": rec["x"],
            "y": rec["y"],
            "vx": rec["vx"],
            "vy": rec["vy"],
            "speed": rec["speed"],
        }
        src = [
            [ev_node["node_id"], event_lines.index(line)],
            [rec["node_id"], rec["row_index"], ["x", "y", "vx", "vy", "speed"]],
        ]
        inputs.append({
            "id": in_id,
            "time": float(rec["frame"]),
            "kind": "arrival" if evtype == "arrival" else "presence",
            "entities": [oid],
            "fields": fields,
            "src": src,
        })
        seen_inputs.add(oid)

    # --- objects that never appear in events (implied present at start) ---
    for oid in obj_desc:
        if oid in seen_inputs:
            continue
        if oid not in motion_by_obj:
            continue
        recs = sorted(motion_by_obj[oid], key=lambda d: d["frame"])
        rec = recs[0]
        inp_id = f"input_obj{oid}_0"
        src = [
            [rec["node_id"], rec["row_index"], ["x", "y", "vx", "vy", "speed"]],
        ]
        inputs.append({
            "id": inp_id,
            "time": float(rec["frame"]),
            "kind": "presence",
            "entities": [oid],
            "fields": {
                "frame": rec["frame"],
                "x": rec["x"],
                "y": rec["y"],
                "vx": rec["vx"],
                "vy": rec["vy"],
                "speed": rec["speed"],
            },
            "src": src,
        })

    # Sort inputs by time ascending
    inputs.sort(key=lambda d: d["time"])
    return inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Everything the process produces: coined events (collisions, exits).
    """
    outcomes = []

    ev_node = node_by_title(doc, f"{scope}: Events")
    if not ev_node:
        return outcomes
    lines = ev_node.get("lines", [])

    for i, line in enumerate(lines):
        m = re.match(r"Frame\s+(\d+):", line)
        if not m:
            continue
        frame = int(m.group(1))
        # skip arrival or presence
        if "enters" in line or "in view" in line:
            continue
        # collision
        if "collides" in line or "collision" in line:
            kind = "collision"
        elif "exits" in line:
            kind = "exit"
        else:
            continue
        objects = _event_objects(line)
        if not objects:
            continue
        outcomes.append({
            "time": float(frame),
            "kind": kind,
            "entities": objects,
            "value": None,
            "src": [[ev_node["node_id"], i]],
        })

    # sort by time
    outcomes.sort(key=lambda d: d["time"])
    return outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """
    Constants for the scope.  None declared here.
    """
    return {}

import re
from typing import List, Dict, Any, Optional

# Helpers assumed to be provided by the evaluation environment
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> list of nodes belonging to the scope
# table_rows(node) -> list of (row_index, {column:cell})

# --------------------------------------------------------------------------- #
# Extraction utilities
# --------------------------------------------------------------------------- #

def _parse_object_line(line: str):
    """Return (id, description) or (None, None) if not an object line."""
    m = re.match(r"Object\s+(\d+):\s*(.*)", line)
    return (m.group(1), m.group(2)) if m else (None, None)

def _parse_event_line(line: str):
    """Return (frame, text) where frame is int or None if no match."""
    m = re.match(r"Frame\s+(\d+):\s*(.*)", line)
    if not m:
        return None, None
    return int(m.group(1)), m.group(2)

def _extract_obj_ids(text: str) -> List[str]:
    """Return list of object ids that appear in the text."""
    return re.findall(r"Object\s+(\d+)", text)


# --------------------------------------------------------------------------- #
# Main interface
# --------------------------------------------------------------------------- #

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """List every distinct entity that the scope's records are about."""
    out = []
    node = node_by_title(doc, f"{scope}: Objects")
    if not node:
        return out
    for idx, line in enumerate(node.get("lines", [])):
        obj_id, desc = _parse_object_line(line)
        if obj_id is not None:
            out.append({"id": obj_id, "description": desc})
    return out


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """The last time point seen in the scope."""
    max_frame = None

    # From Events
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node:
        for line in ev_node.get("lines", []):
            frame, _ = _parse_event_line(line)
            if frame is not None:
                max_frame = frame if max_frame is None else max(max_frame, frame)

    # From Motion log
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    if ml_node:
        for row_idx, row in enumerate(ml_node.get("table", {}).get("rows", [])):
            try:
                frame = int(row[0])
                max_frame = frame if max_frame is None else max(max_frame, frame)
            except Exception:
                pass

    return float(max_frame) if max_frame is not None else None


# --------------------------------------------------------------------------- #
# Helper for reading motion rows
# --------------------------------------------------------------------------- #

def _get_motion_rows(node):
    """Return list of (row_index, dict) for the motion log table."""
    rows_data = node.get("table", {}).get("rows", [])
    return [(idx, dict(zip(node["table"]["columns"], row))) for idx, row in enumerate(rows_data)]


# --------------------------------------------------------------------------- #
# Inputs
# --------------------------------------------------------------------------- #

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    out = []

    # Entity description nodes (metadata)
    obj_node = node_by_title(doc, f"{scope}: Objects")
    if obj_node:
        for idx, line in enumerate(obj_node.get("lines", [])):
            obj_id, desc = _parse_object_line(line)
            if obj_id is not None:
                out.append({
                    "id": f"meta_{obj_id}",
                    "time": None,
                    "kind": "metadata",
                    "entities": [obj_id],
                    "fields": {"description": desc},
                    "src": [[obj_node["node_id"], idx]],
                })

    # Build mapping of motion data by object id
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    motion_by_obj = {}
    motion_rows = []
    if ml_node:
        motion_rows = _get_motion_rows(ml_node)
        for row_index, row in motion_rows:
            obj_full = row.get("object", "")
            m = re.match(r"(\d+)\s", obj_full)
            if not m:
                continue
            obj_id = m.group(1)
            rec = {
                "frame": float(row.get("frame", "0")),
                "frame_raw": row.get("frame", ""),
                "x": float(row.get("x", "0")),
                "y": float(row.get("y", "0")),
                "vx": float(row.get("vx", "0")),
                "vy": float(row.get("vy", "0")),
                "speed": float(row.get("speed", "0")),
                "node_id": ml_node["node_id"],
                "row_index": row_index
            }
            motion_by_obj.setdefault(obj_id, []).append(rec)

    # Events: arrivals and entries
    ev_node = node_by_title(doc, f"{scope}: Events")
    event_lines = ev_node.get("lines", []) if ev_node else []

    handled_objs = set()

    for line_index, line in enumerate(event_lines):
        frame, text = _parse_event_line(line)
        if frame is None:
            continue
        objs = _extract_obj_ids(text)
        if not objs:
            continue
        # Determine kind based on content
        if "enters" in text or "in view" in text:
            kind = "arrival"
        else:
            continue  # skip other event types here

        for obj_id in objs:
            if obj_id in handled_objs:
                continue
            # Find first motion record at or after frame
            recs = motion_by_obj.get(obj_id, [])
            rec = None
            for r in sorted(recs, key=lambda x: x["frame"]):
                if r["frame"] >= frame:
                    rec = r
                    break
            if rec is None and recs:
                rec = recs[0]
            if rec is None:
                continue

            out.append({
                "id": f"input_{obj_id}_{frame}",
                "time": float(rec["frame"]),
                "kind": kind,
                "entities": [obj_id],
                "fields": {
                    "frame": rec["frame"],
                    "x": rec["x"],
                    "y": rec["y"],
                    "vx": rec["vx"],
                    "vy": rec["vy"],
                    "speed": rec["speed"],
                },
                "src": [
                    [ev_node["node_id"], line_index],
                    [ml_node["node_id"], rec["row_index"], ["frame", "object", "x", "y", "vx", "vy", "speed"]],
                ],
            })
            handled_objs.add(obj_id)

    # Objects with no explicit arrival: present from start
    for obj_id, recs in motion_by_obj.items():
        if obj_id in handled_objs:
            continue
        rec = sorted(recs, key=lambda x: x["frame"])[0]
        out.append({
            "id": f"input_{obj_id}_start",
            "time": float(rec["frame"]),
            "kind": "presence",
            "entities": [obj_id],
            "fields": {
                "frame": rec["frame"],
                "x": rec["x"],
                "y": rec["y"],
                "vx": rec["vx"],
                "vy": rec["vy"],
                "speed": rec["speed"],
            },
            "src": [
                [ml_node["node_id"], rec["row_index"], ["frame", "object", "x", "y", "vx", "vy", "speed"]],
            ],
        })
        handled_objs.add(obj_id)

    # Ensure deterministic order
    out.sort(key=lambda d: (d["time"] if d["time"] is not None else 0, d["id"]))
    return out


# --------------------------------------------------------------------------- #
# Outcomes
# --------------------------------------------------------------------------- #

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    out = []

    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node:
        for line_index, line in enumerate(ev_node.get("lines", [])):
            frame, text = _parse_event_line(line)
            if frame is None:
                continue
            if "collides" in text or "collision" in text:
                kind = "collision"
            elif "exits" in text:
                kind = "exit"
            else:
                continue
            objs = _extract_obj_ids(text)
            if not objs:
                continue
            out.append({
                "time": float(frame),
                "kind": kind,
                "entities": objs,
                "value": None,
                "src": [[ev_node["node_id"], line_index]],
            })

    # Motion log rows as state outcomes (to satisfy src coverage)
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    if ml_node:
        motion_rows = _get_motion_rows(ml_node)
        for row_index, row in motion_rows:
            obj_full = row.get("object", "")
            m = re.match(r"(\d+)\s", obj_full)
            if not m:
                continue
            obj_id = m.group(1)
            out.append({
                "time": float(row.get("frame", "0")),
                "kind": "state",
                "entities": [obj_id],
                "value": None,
                "src": [[ml_node["node_id"], row_index, ["frame", "object", "x", "y", "vx", "vy", "speed"]]],
            })

    # Sort outcomes by time
    out.sort(key=lambda d: (d["time"] if d["time"] is not None else 0, d["kind"]))
    return out


# --------------------------------------------------------------------------- #
# Parameters
# --------------------------------------------------------------------------- #

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Placeholder: no constants defined in the document."""
    return {}

