# Block 1: Find all times where any object is stationary (speed < 0.1)
def stationary_times():
    all_rows = []
    for node in doc["nodes"]:
        if node["kind"] == "table" and "Motion log" in node["title"]:
            rows = _get_motion_rows(node)
            for idx, r in rows:
                all_rows.append(r)
    stat_times = [(r["frame"], r["object"]) for r in all_rows if r["speed"] < 0.1]
    # Take the earliest stationary time per object
    earliest = {}
    for f, obj in stat_times:
        if obj not in earliest or f < earliest[obj]:
            earliest[obj] = f
    print("Earliest stationary times per object:")
    for obj, f in sorted(earliest.items()):
        print(f"Object {obj}: frame {f}")

