# Block 2: Compute distances between colliding objects right before collision
def collision_distances(scope):
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    rows = _get_motion_rows(ml_node)
    motion = {}
    for idx, r in rows:
        obj = r["object"]
        obj_id = re.match(r"(\d+)\s", obj).group(1)
        motion.setdefault(obj_id, []).append(r)
    ev_node = node_by_title(doc, f"{scope}: Events")
    if not ev_node:
        return
    for line_index, line in enumerate(ev_node.get("lines", [])):
        frame, text = _parse_event_line(line)
        if frame is None or "collides" not in text:
            continue
        objs = _extract_obj_ids(text)
        if len(objs) < 2:
            continue
        # find nearest motion record before collision frame
        dists = []
        for o in objs:
            recs = motion.get(o, [])
            rec = min(recs, key=lambda x: abs(float(x["frame"]) - frame), default=None)
            if rec is None:
                continue
            dists.append((float(rec["x"]), float(rec["y"])))
        if len(dists) == 2:
            dx = dists[0][0] - dists[1][0]
            dy = dists[0][1] - dists[1][1]
            dist = (dx**2 + dy**2)**0.5
            print(f"Collision at frame {frame} between {objs[0]} and {objs[1]}: distance = {dist:.3f}")
