import re
from typing import List, Dict, Any, Optional

def _record_id(node_id: str, row_index: int, cols: List[str]) -> List[Any]:
    """Convenience for building a `src` reference."""
    return [[node_id, row_index, cols]]

def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """Recreate the state and event outcomes that already exist in the scope."""
    outcomes: List[Dict[str, Any]] = []

    # ----- State outcomes from the motion log --------------------------------
    ml_node = node_by_title(doc, f"{scope}: Motion log")
    if ml_node:
        ml_rows = _get_motion_rows(ml_node)
        for row_index, row in ml_rows:
            obj_field = row.get("object", "")
            m = re.match(r"(\d+)\s", obj_field)
            if not m:
                continue
            obj_id = m.group(1)
            frame = float(row.get("frame", "0"))
            if start is not None and frame < start:
                continue
            if horizon is not None and frame > horizon:
                continue
            outcomes.append({
                "time": frame,
                "kind": "state",
                "entities": [obj_id],
                "value": None,
                "src": [[ml_node["node_id"], row_index,
                         ["frame", "object", "x", "y", "vx", "vy", "speed"]]],
            })

    # ----- Event outcomes (collision, exit) ---------------------------------
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node:
        for line_index, line in enumerate(ev_node.get("lines", [])):
            frame, text = _parse_event_line(line)
            if frame is None:
                continue
            if start is not None and frame < start:
                continue
            if horizon is not None and frame > horizon:
                continue
            kind = None
            if "collides" in text or "collision" in text:
                kind = "collision"
            elif "exits" in text:
                kind = "exit"
            if kind is None:
                continue
            objs = _extract_obj_ids(text)
            if not objs:
                continue
            outcomes.append({
                "time": float(frame),
                "kind": kind,
                "entities": objs,
                "value": None,
                "src": [[ev_node["node_id"], line_index]],
            })

    outcomes.sort(key=lambda d: (d["time"] if d["time"] is not None else 0, d["kind"]))
    return outcomes
